//! # hanihi-session
//!
//! Read-only session introspection for hānihi. Prints the same
//! `/session` summary the REPL shows — session name/id, current turn,
//! the `[turn N | tool calls | tokens in/out]` line, and cumulative
//! token usage — by reading a session directory's `session.json` and
//! `events.jsonl` directly, without connecting to any model or taking
//! the session lock.

use std::path::{Path, PathBuf};

/// Data needed to reproduce a session summary line.
struct SessionInfo {
    id: String,
    name: String,
    model: String,
    turn: u64,
    /// Most recent completed turn's token usage (input, output).
    last_in: u64,
    last_out: u64,
    /// Tool calls in the most recent completed turn.
    last_tool_calls: u64,
    /// Cumulative token usage across all turns.
    cum_in: u64,
    cum_out: u64,
}

/// Raw fields we need out of `session.json`.
#[derive(serde::Deserialize)]
struct Meta {
    #[serde(default)]
    id: String,
    #[serde(default)]
    name: String,
    #[serde(default)]
    model: String,
}

fn main() {
    // Positional: working dir (default ./working) then session name
    // (default default-session). Simplest possible CLI, no clap dependency.
    let args: Vec<String> = std::env::args().skip(1).collect();
    let (working_dir, session_name) = match args.as_slice() {
        [] => (PathBuf::from("./working"), "default-session".to_string()),
        [name] => (PathBuf::from("./working"), name.clone()),
        [dir, name] => (PathBuf::from(dir), name.clone()),
        _ => {
            eprintln!("usage: hanihi-session [WORKING_DIR] [SESSION_NAME]");
            std::process::exit(2);
        }
    };

    match print_session(&working_dir, &session_name) {
        Ok(()) => {}
        Err(e) => {
            eprintln!("error: {e}");
            std::process::exit(1);
        }
    }
}

fn print_session(working_dir: &Path, name: &str) -> Result<(), String> {
    let dir = working_dir.join("sessions").join(name);
    let meta = read_meta(&dir)?;
    let events = read_events(&dir)?;

    let info = summarize(&meta, &events);

    // Mirror the REPL's `/session` output.
    println!(
        "session: '{}' (id={}) turn={} max_turns=(n/a outside REPL)",
        info.name, info.id, info.turn
    );
    println!(
        "[turn {} | tool calls: {} | tokens: {} in / {} out]",
        info.turn, info.last_tool_calls, info.last_in, info.last_out
    );
    println!(
        "cumulative tokens: {} in / {} out | model: {}",
        info.cum_in, info.cum_out, info.model
    );
    Ok(())
}

/// Read and parse `session.json`.
fn read_meta(dir: &Path) -> Result<Meta, String> {
    let path = dir.join("session.json");
    let bytes = std::fs::read(&path).map_err(|e| format!("reading {}: {e}", path.display()))?;
    serde_json::from_slice(&bytes).map_err(|e| format!("parsing {}: {e}", path.display()))
}

/// Parse each `events.jsonl` line into the minimal shape we need.
fn read_events(dir: &Path) -> Result<Vec<serde_json::Value>, String> {
    let path = dir.join("events.jsonl");
    let content =
        std::fs::read_to_string(&path).map_err(|e| format!("reading {}: {e}", path.display()))?;
    let mut entries = Vec::new();
    for (i, line) in content.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let value: serde_json::Value =
            serde_json::from_str(line).map_err(|e| format!("events.jsonl line {}: {e}", i + 1))?;
        entries.push(value);
    }
    Ok(entries)
}

/// Fold the events into a [`SessionInfo`].
fn summarize(meta: &Meta, events: &[serde_json::Value]) -> SessionInfo {
    let mut info = SessionInfo {
        id: meta.id.clone(),
        name: meta.name.clone(),
        model: meta.model.clone(),
        turn: 0,
        last_in: 0,
        last_out: 0,
        last_tool_calls: 0,
        cum_in: 0,
        cum_out: 0,
    };

    for entry in events {
        let Some(kind) = entry.get("kind").and_then(|k| k.as_str()) else {
            continue;
        };
        let Some(turn) = entry.get("turn").and_then(|t| t.as_u64()) else {
            continue;
        };
        let Some(data) = entry.get("data") else {
            continue;
        };

        match kind {
            "turn_complete" => {
                info.turn = turn;
                info.last_in = 0;
                info.last_out = 0;
                info.last_tool_calls = data.get("tool_calls").and_then(|t| t.as_u64()).unwrap_or(0);
            }
            "llm_response" if turn == info.turn => {
                if let Some(usage) = data.get("usage") {
                    info.last_in += usage
                        .get("input_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.last_out += usage
                        .get("output_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.cum_in += usage
                        .get("input_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.cum_out += usage
                        .get("output_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                }
            }
            "llm_response" => {
                if let Some(usage) = data.get("usage") {
                    info.cum_in += usage
                        .get("input_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.cum_out += usage
                        .get("output_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                }
            }
            _ => {}
        }
    }

    info
}

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use clap::Parser;
use hanihi_core::session::SessionManager;
use hanihi_core::session::log::read_log_tolerant;

const DEFAULT_WORKING_DIR: &str = "./working";

#[derive(Debug, Parser)]
#[command(name = "analyse", about = "Inspect hānihi session logs")]
struct Args {
    /// Analyse this session: print kind and timestamp per log entry.
    #[arg(long, value_name = "SESSION")]
    session: Option<String>,
}

fn main() -> ExitCode {
    let args = Args::parse();
    let working_dir = PathBuf::from(DEFAULT_WORKING_DIR);

    match args.session {
        Some(name) => match analyse_session(&working_dir, &name) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("{e}");
                ExitCode::FAILURE
            }
        },
        None => match list_sessions(&working_dir) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("{e}");
                ExitCode::FAILURE
            }
        },
    }
}

/// Print names of all sessions on disk, one per line.
fn list_sessions(working_dir: &Path) -> Result<(), String> {
    let names = session_names(working_dir)?;
    if names.is_empty() {
        println!("no sessions");
    } else {
        for name in names {
            println!("{name}");
        }
    }
    Ok(())
}

/// Names of all session directories under `working_dir/sessions`.
fn session_names(working_dir: &Path) -> Result<Vec<String>, String> {
    SessionManager::new(working_dir)
        .list()
        .map_err(|e| format!("error listing sessions: {e}"))
}

/// Print `kind<TAB>ts` for every entry in one session's `events.jsonl`.
///
/// Bad lines are reported as warnings on stderr but do not abort the read.
fn analyse_session(working_dir: &Path, name: &str) -> Result<(), String> {
    let path = working_dir.join("sessions").join(name).join("events.jsonl");
    let outcome =
        read_log_tolerant(&path).map_err(|e| format!("error reading {}: {e}", path.display()))?;

    for entry in &outcome.entries {
        println!("{}\t{}", entry.kind(), entry.ts().to_rfc3339());
    }
    for err in &outcome.errors {
        eprintln!(
            "warning: {} line {}: {}",
            path.display(),
            err.line,
            err.message
        );
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use hanihi_core::session::log::LogEntry;

    const USER_INPUT: &str = r#"{"schema":1,"kind":"user_input","ts":"2026-01-01T00:00:00Z","turn":1,"data":{"text":"hi"}}"#;
    const TURN_COMPLETE: &str = r#"{"schema":1,"kind":"turn_complete","ts":"2026-01-01T00:00:01Z","turn":1,"data":{"text":"x","tool_calls":0}}"#;

    fn tmp_dir(tag: &str) -> PathBuf {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock after epoch")
            .as_nanos();
        std::env::temp_dir().join(format!(
            "hanihi-analyse-{tag}-{}-{nanos}",
            std::process::id()
        ))
    }

    #[test]
    fn cli_defaults_to_listing_sessions() {
        let args = Args::try_parse_from(["analyse"]).expect("parse");
        assert_eq!(args.session, None);
    }

    #[test]
    fn cli_accepts_session_flag() {
        let args = Args::try_parse_from(["analyse", "--session", "foo"]).expect("parse");
        assert_eq!(args.session.as_deref(), Some("foo"));
    }

    #[test]
    fn maps_kind_for_parsed_entry() {
        let entry: LogEntry = serde_json::from_str(USER_INPUT).expect("parse");
        assert_eq!(entry.kind(), "user_input");
        assert_eq!(entry.ts().to_rfc3339(), "2026-01-01T00:00:00+00:00");
    }

    #[test]
    fn parses_valid_entries_with_tolerant_reader() {
        let log = format!("{USER_INPUT}\n{TURN_COMPLETE}\n");
        let outcome = hanihi_core::session::log::parse_log_tolerant(&log);
        assert_eq!(outcome.entries.len(), 2);
        assert!(outcome.errors.is_empty());
    }

    #[test]
    fn reports_bad_lines_as_errors_not_failures() {
        let log = format!("{USER_INPUT}\nnot json\n");
        let outcome = hanihi_core::session::log::parse_log_tolerant(&log);
        assert_eq!(outcome.entries.len(), 1);
        assert_eq!(outcome.errors.len(), 1);
        assert_eq!(outcome.errors[0].line, 2);
    }

    #[test]
    fn session_names_lists_existing_dirs_sorted() {
        let dir = tmp_dir("list");
        std::fs::create_dir_all(dir.join("sessions").join("alpha")).expect("create alpha");
        std::fs::create_dir_all(dir.join("sessions").join("beta")).expect("create beta");

        let names = session_names(&dir).expect("list");
        assert_eq!(names, vec!["alpha".to_string(), "beta".to_string()]);

        std::fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn session_names_empty_without_sessions_dir() {
        let dir = tmp_dir("empty");
        let names = session_names(&dir).expect("list");
        assert!(names.is_empty());
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }
}

